"use client";

import { useEffect, useId, useRef, useState, type ComponentProps, type KeyboardEvent } from "react";
import { animate, useMotionValue, useMotionValueEvent, useReducedMotion, type AnimationPlaybackControls } from "motion/react";
import { arcPath, formatCompact, seriesColor } from "@/lib/chart";
import { ChartTable, chartFocus, useChartNav, useDrawIn, type Format, EffectLayer, type ChartEffect } from "@/components/ui/chart";
import { cn } from "@/lib/utils";

export type SpendCategory = {
  label: string;
  value: number;
  budget?: number;
  color?: string;
  children?: Omit<SpendCategory, "children">[];
};

export type SpendingRingProps = Omit<ComponentProps<"figure">, "children"> & {
  data: SpendCategory[];
  label: string;
  format?: Format;
  thickness?: number;
  totalLabel?: string;
  effect?: ChartEffect;
};

const C = 100;
const TAU = Math.PI * 2;
// space between tiles along the middle of the ring, in chart units
const GAP = 3.5;
// tiles are drawn this much smaller and stroked back out, which rounds every corner
const SOFT = 4;
const LIFT = 4;
const SHADES = [0, 0.12, -0.12, 0.2, -0.2, 0.06];
const clamp = (n: number) => Math.min(Math.max(n, 0), 1);
const sum = (list: { value: number }[]) => list.reduce((a, d) => a + Math.max(d.value, 0), 0);
// black on light fills, white on dark ones, so amounts read in both themes
const inkOn = (fill: string) => `oklch(from ${fill} calc((0.7 - l) * 100) 0 0)`;

type Tile = { key: string; from: number; to: number; color: string; value: number; budget?: number; opacity: number; width: number; text: number };
type Row = { key: string; label: string; value: number; budget?: number; share: number; parent?: string; opens: boolean };

export function SpendingRing({
  data,
  label,
  format = formatCompact,
  thickness = 34,
  totalLabel = "Spent",
  effect,
  className,
  ...props
}: SpendingRingProps) {
  const hatch = useId().replace(/[^\w-]/g, "");
  const reduce = useReducedMotion();
  const progress = useDrawIn();
  const [open, setOpen] = useState<string | null>(null);
  // the category whose parts are drawn; it stays while it folds back home
  const [unfolded, setUnfolded] = useState<string | null>(null);
  const spring = useMotionValue(0);
  const [p, setP] = useState(0);
  useMotionValueEvent(spring, "change", setP);
  const run = useRef<{ token: number; controls?: AnimationPlaybackControls }>({ token: 0 });

  const total = sum(data);
  const home = data.find((d) => d.label === unfolded);
  const parts = home?.children ?? [];
  const rows: Row[] =
    open && home && open === unfolded
      ? parts.map((c) => ({ key: `${home.label}/${c.label}`, label: c.label, value: c.value, budget: c.budget, share: sum(parts) ? c.value / sum(parts) : 0, parent: home.label, opens: false }))
      : data.map((d) => ({ key: d.label, label: d.label, value: d.value, budget: d.budget, share: total ? d.value / total : 0, opens: !!d.children?.length }));
  const { active, setActive, handlers } = useChartNav(rows.length);

  const go = async (next: string | null) => {
    const token = ++run.current.token;
    run.current.controls?.stop();
    setActive(null);
    setOpen(next);
    const to = (target: number) => {
      if (reduce) return spring.jump(target);
      run.current.controls = animate(spring, target, { type: "spring", stiffness: 140, damping: 22 });
      return run.current.controls;
    };
    // another category has to fold home before the next one can bloom
    if (unfolded && unfolded !== next && spring.get() > 0.01) await to(0);
    if (token !== run.current.token) return;
    setUnfolded(next);
    if (next) await to(1);
  };

  useEffect(() => {
    if (!open) return;
    const onKey = (event: globalThis.KeyboardEvent) => event.key === "Escape" && go(null);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });

  const R = C - thickness / 2 - LIFT - 2;
  const gap = GAP / R;
  const spans = data.map((d) => (total ? (TAU * Math.max(d.value, 0)) / total : 0) * progress);
  const starts = spans.map((_, i) => spans.slice(0, i).reduce((a, s) => a + s, 0));
  const k = data.findIndex((d) => d.label === unfolded);
  const tiles: Tile[] = [];
  const tile = (d: { label: string; value: number; budget?: number }, key: string, color: string, from: number, to: number, rest: Partial<Tile> = {}) =>
    tiles.push({ key, from, to, color, value: d.value, budget: d.budget, opacity: 1, width: thickness, text: 1, ...rest });

  if (k < 0) {
    data.forEach((d, i) => tile(d, d.label, seriesColor(i % 5, d.color), starts[i] + gap / 2, starts[i] + spans[i] - gap / 2));
  } else {
    // the open tile blooms from its middle to the whole ring and squeezes the others out of what is left
    const span = spans[k] + (TAU - spans[k]) * p;
    const from = starts[k] + spans[k] / 2 - span / 2;
    const squeeze = TAU - spans[k] > 0 ? (TAU - span) / (TAU - spans[k]) : 0;
    let at = from + span;
    for (let step = 1; step < data.length; step++) {
      const i = (k + step) % data.length;
      const len = spans[i] * squeeze;
      const g = gap * (1 - p);
      tile(data[i], data[i].label, seriesColor(i % 5, data[i].color), at + g / 2, at + len - g / 2, { opacity: clamp(1 - p * 1.5), width: thickness * (1 - p / 2), text: clamp(1 - p * 3) });
      at += len;
    }
    const parent = seriesColor(k % 5, data[k].color);
    const split = clamp(p / 0.3);
    const whole = sum(parts);
    let c0 = from;
    parts.forEach((c, j) => {
      const len = whole ? (span * Math.max(c.value, 0)) / whole : 0;
      const g = j === 0 || j === parts.length - 1 ? gap : gap * split;
      const shade = c.color ?? `oklch(from ${parent} calc(l + ${SHADES[j % SHADES.length]}) c h)`;
      tile(c, `${data[k].label}/${c.label}`, split >= 1 ? shade : `color-mix(in oklab, ${shade} ${split * 100}%, ${parent})`, c0 + (j === 0 ? gap : g) / 2, c0 + len - (j === parts.length - 1 ? gap : g) / 2, { text: clamp((p - 0.45) / 0.4) });
      c0 += len;
    });
    // the parent covers its parts until they have pulled apart, hiding the seams
    tile(data[k], data[k].label, parent, from + gap / 2, from + span - gap / 2, { opacity: 1 - split, text: 0 });
  }

  const current = active === null ? null : rows[active];
  const opened = open ? data.find((d) => d.label === open) : undefined;
  const note = (value: number, budget: number | undefined, fallback: string) =>
    budget === undefined ? { text: fallback, over: false } : value > budget ? { text: `${format(value - budget)} over budget`, over: true } : { text: `of ${format(budget)} budget`, over: false };
  const centre = current
    ? { label: current.label, value: current.value, ...note(current.value, current.budget, `${Math.round(current.share * 100)}% of ${current.parent ?? "spending"}`) }
    : opened
      ? { label: opened.label, value: opened.value, ...note(opened.value, opened.budget, `${Math.round((total ? opened.value / total : 0) * 100)}% of spending`) }
      : { label: totalLabel, value: total, text: "", over: false };
  const settled = p < 0.02 || p > 0.98;

  const onKeyDown = (event: KeyboardEvent) => {
    if ((event.key === "Enter" || event.key === " ") && current?.opens) {
      event.preventDefault();
      go(current.key);
    } else handlers.onKeyDown(event);
  };

  return (
    <figure data-slot="spending-ring" className={cn("flex flex-col items-center", className)} {...props}>
      <div
        role="group"
        aria-roledescription="chart"
        aria-label={`${opened ? `${opened.label}, by part` : label}. Use the arrow keys to read each category${opened ? ", Escape to go back" : ", Enter to open one"}.`}
        className={cn("relative aspect-square w-full max-w-[260px] rounded-full", chartFocus)}
        {...handlers}
        onKeyDown={onKeyDown}
      >
        <svg viewBox="0 0 200 200" aria-hidden className="size-full overflow-visible">
          <defs>
            <pattern id={hatch} width={5} height={5} patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
              <rect width={5} height={5} className="fill-red-500 dark:fill-red-400" />
              <rect width={2} height={5} fill="rgb(255 255 255 / 0.55)" />
            </pattern>
          </defs>
          <EffectLayer effect={effect}>
            {tiles.map((t) => {
              if (t.to - t.from <= (2 * SOFT) / R || t.opacity <= 0.01) return null;
              const index = rows.findIndex((r) => r.key === t.key);
              const lifted = active !== null && index === active;
              const quiet = active !== null && index !== active;
              const mid = (t.from + t.to) / 2;
              const r0 = R - t.width / 2 + SOFT;
              const r1 = R + t.width / 2 - SOFT;
              const s = SOFT / R;
              const over = t.budget !== undefined && t.value > t.budget ? (t.value - t.budget) / t.value : 0;
              return (
                <g
                  key={t.key}
                  opacity={t.opacity * (quiet ? 0.35 : 1)}
                  transform={lifted ? `translate(${(Math.sin(mid) * LIFT).toFixed(2)} ${(-Math.cos(mid) * LIFT).toFixed(2)})` : undefined}
                  onPointerEnter={() => settled && index >= 0 && setActive(index)}
                  onClick={() => index >= 0 && rows[index].opens && go(t.key)}
                  className={cn("transition-[opacity,transform] duration-200 motion-reduce:transition-none", index >= 0 && rows[index].opens && "cursor-pointer")}
                >
                  <path d={arcPath(C, C, r1, r0, t.from + s, t.to - s)} style={{ fill: t.color, stroke: t.color }} strokeWidth={SOFT * 2} strokeLinejoin="round" />
                  {over > 0 && (
                    <path
                      d={arcPath(C, C, r1, r0, Math.max(t.to - (t.to - t.from) * over, t.from + s), t.to - s)}
                      fill={`url(#${hatch})`}
                      stroke={`url(#${hatch})`}
                      strokeWidth={SOFT * 2}
                      strokeLinejoin="round"
                    />
                  )}
                </g>
              );
            })}
          </EffectLayer>
          {tiles.map((t) => {
            if (t.to - t.from <= (2 * SOFT) / R || t.opacity <= 0.01) return null;
            const index = rows.findIndex((r) => r.key === t.key);
            const lifted = active !== null && index === active;
            const quiet = active !== null && index !== active;
            const mid = (t.from + t.to) / 2;
            const text = format(t.value);
            const fits = (t.to - t.from) * R >= text.length * 5.6 + 12 && t.width > 24;
            return (
              <g
                key={t.key}
                opacity={t.opacity * (quiet ? 0.35 : 1)}
                transform={lifted ? `translate(${(Math.sin(mid) * LIFT).toFixed(2)} ${(-Math.cos(mid) * LIFT).toFixed(2)})` : undefined}
                className="pointer-events-none transition-[opacity,transform] duration-200 motion-reduce:transition-none"
              >
                <text
                  x={(C + R * Math.sin(mid)).toFixed(2)}
                  y={(C - R * Math.cos(mid)).toFixed(2)}
                  textAnchor="middle"
                  dominantBaseline="central"
                  opacity={fits ? t.text : 0}
                  style={{ fill: inkOn(t.color) }}
                  className="pointer-events-none select-none font-mono text-[9.5px] font-semibold tabular-nums"
                >
                  {text}
                </text>
              </g>
            );
          })}
        </svg>
        <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
          <button
            type="button"
            tabIndex={-1}
            onClick={() => go(null)}
            aria-hidden
            className={cn(
              "mb-1 rounded-full px-2 py-0.5 text-xs font-semibold text-muted-foreground transition-[opacity,translate] duration-200 hover:bg-muted hover:text-foreground motion-reduce:transition-none",
              opened ? "pointer-events-auto opacity-100" : "-translate-y-1 opacity-0",
            )}
          >
            ‹ All
          </button>
          <span className="max-w-[60%] truncate text-xs font-semibold text-muted-foreground">{centre.label}</span>
          <span className="font-mono text-2xl font-medium tabular-nums">{format(centre.value)}</span>
          <span className={cn("h-4 text-xs", centre.over ? "text-red-600 dark:text-red-400" : "text-muted-foreground")}>{centre.text}</span>
        </div>
        <p aria-live="polite" className="sr-only">
          {current ? `${current.label}: ${format(current.value)}, ${centre.text}` : opened ? `${opened.label} open` : ""}
        </p>
      </div>
      <ChartTable
        caption={label}
        columns={["Category", "Spent", "Budget"]}
        rows={data.flatMap((d) => [
          [d.label, format(d.value), d.budget === undefined ? "" : format(d.budget)],
          ...(d.children ?? []).map((c) => [`${d.label}, ${c.label}`, format(c.value), c.budget === undefined ? "" : format(c.budget)]),
        ])}
      />
    </figure>
  );
}

"use client";

import {
  useEffect,
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { animate, AnimatePresence, motion, useReducedMotion } from "motion/react";
import { formatCompact, niceTicks, scaleLinear, seriesColor } from "@/lib/chart";
import { cn } from "@/lib/utils";

export type ChartDatum = Record<string, string | number>;

export type ChartSeries = {
  key: string;
  label?: string;
  color?: string;
};

export type Format = (value: number) => string;

// a paint applied to a chart's marks only: svg defs it needs, a filter for the marks, and an optional series paint
export type ChartEffect = {
  defs: ReactNode;
  filter?: string;
  fill?: (color: string, index: number) => string;
};

// wraps marks inside an svg so the effect touches them and leaves axes, labels and tooltips plain
export function EffectLayer({ effect, children }: { effect?: ChartEffect; children: ReactNode }) {
  if (!effect) return <>{children}</>;
  return (
    <>
      <defs>{effect.defs}</defs>
      <g filter={effect.filter}>{children}</g>
    </>
  );
}

// html and canvas charts keep the effect's defs here and put effect.filter on their marks as a css filter
export function EffectDefs({ effect }: { effect?: ChartEffect }) {
  if (!effect) return null;
  return (
    <svg aria-hidden className="pointer-events-none absolute size-0 overflow-hidden">
      <defs>{effect.defs}</defs>
    </svg>
  );
}

export function useChartWidth<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [width, setWidth] = useState(0);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const observer = new ResizeObserver(([entry]) => setWidth(Math.round(entry.contentRect.width)));
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  return [ref, width] as const;
}

// one value from 0 to 1 that drives every draw-in, skipped under reduced motion
export function useDrawIn(delay = 0) {
  const reduce = useReducedMotion();
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    if (reduce) return;
    const controls = animate(0, 1, { duration: 0.9, delay, ease: [0.22, 1, 0.36, 1], onUpdate: setProgress });
    return () => controls.stop();
  }, [reduce, delay]);

  return reduce ? 1 : progress;
}

export function ChartLegend({ items }: { items: { label: string; color: string }[] }) {
  return (
    <ul className="flex flex-wrap gap-x-4 gap-y-1.5 text-xs font-semibold text-muted-foreground">
      {items.map((item) => (
        <li key={item.label} className="flex items-center gap-1.5">
          <span aria-hidden className="size-2.5 rounded-full" style={{ background: item.color }} />
          {item.label}
        </li>
      ))}
    </ul>
  );
}

export function ChartTable({ caption, columns, rows }: { caption: string; columns: string[]; rows: ReactNode[][] }) {
  return (
    <table className="sr-only">
      <caption>{caption}</caption>
      <thead>
        <tr>
          {columns.map((column) => (
            <th key={column} scope="col">
              {column}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row, i) => (
          <tr key={i}>
            {row.map((cell, j) => (j === 0 ? <th key={j} scope="row">{cell}</th> : <td key={j}>{cell}</td>))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export type TooltipRow = { label: string; value: string; color?: string };

export function ChartTooltip({
  x,
  y,
  width,
  title,
  rows,
}: {
  x: number;
  y: number;
  width: number;
  title?: string;
  rows: TooltipRow[] | null;
}) {
  const reduce = useReducedMotion();
  const left = Math.min(Math.max(x, 72), Math.max(width - 72, 72));

  return (
    <AnimatePresence>
      {rows && (
        <motion.div
          aria-hidden
          initial={{ opacity: 0, scale: reduce ? 1 : 0.96 }}
          animate={{ opacity: 1, scale: 1, left, top: y }}
          exit={{ opacity: 0 }}
          transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 520, damping: 40 }}
          className="pointer-events-none absolute z-10 -translate-x-1/2 -translate-y-[calc(100%+12px)] whitespace-nowrap rounded-[16px] border border-foreground/[0.06] bg-background/90 px-3 py-2 text-xs shadow-lg backdrop-blur-md [corner-shape:squircle]"
        >
          {title && <p className="mb-1 font-semibold text-muted-foreground">{title}</p>}
          {rows.map((row) => (
            <p key={row.label} className="flex items-center gap-2">
              {row.color && <span className="size-2 rounded-full" style={{ background: row.color }} />}
              <span className="text-muted-foreground">{row.label}</span>
              <span className="ml-auto pl-3 font-mono font-medium tabular-nums text-foreground">{row.value}</span>
            </p>
          ))}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// arrow keys walk the data (up and down by a row in a grid), home and end jump, escape lets go
export function useChartNav(count: number, columns = 1) {
  const [active, setActive] = useState<number | null>(null);

  const onKeyDown = (event: KeyboardEvent) => {
    const row = columns > 1 ? columns : 1;
    const step = { ArrowRight: 1, ArrowDown: row, ArrowLeft: -1, ArrowUp: -row }[event.key];
    let next: number | null | undefined;
    if (step) next = active === null ? 0 : (active + step + count) % count;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = count - 1;
    else if (event.key === "Escape") next = null;
    if (next === undefined) return;
    event.preventDefault();
    setActive(next);
  };

  return {
    active,
    setActive,
    handlers: {
      tabIndex: 0,
      onKeyDown,
      onFocus: () => setActive((current) => current ?? count - 1),
      onBlur: () => setActive(null),
      onPointerLeave: () => setActive(null),
    },
  };
}

export const chartFocus =
  "rounded-[inherit] outline-hidden focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-brand";

export type CartesianContext = {
  data: ChartDatum[];
  series: (ChartSeries & { color: string; label: string })[];
  width: number;
  height: number;
  x: (index: number) => number;
  band: number;
  y: (value: number) => number;
  top: number;
  floor: number;
  active: number | null;
  progress: number;
};

export type CartesianChartProps = Omit<ComponentProps<"figure">, "children"> & {
  data: ChartDatum[];
  index: string;
  series: ChartSeries[];
  label: string;
  height?: number;
  format?: Format;
  stacked?: boolean;
  zero?: boolean;
  bars?: boolean;
  bare?: boolean;
  grid?: boolean;
  floating?: boolean;
  legend?: boolean;
  header?: ReactNode;
  effect?: ChartEffect;
  slot: string;
  children: (context: CartesianContext) => ReactNode;
  // drawn above the marks and outside any effect: hover dots, tags, handles
  overlay?: (context: CartesianContext) => ReactNode;
};

const MARGIN = { top: 12, right: 8, bottom: 28, left: 40 };
const BARE = { top: 6, right: 6, bottom: 6, left: 6 };

export function CartesianChart({
  data,
  index,
  series: input,
  label,
  height = 240,
  format = formatCompact,
  stacked = false,
  zero = false,
  bars = false,
  bare = false,
  grid = true,
  floating = false,
  legend = true,
  header,
  effect,
  slot,
  children,
  overlay,
  className,
  ...props
}: CartesianChartProps) {
  const [ref, width] = useChartWidth<HTMLDivElement>();
  const { active, setActive, handlers } = useChartNav(data.length);
  const progress = useDrawIn();
  const margin = bare ? BARE : grid ? MARGIN : { ...MARGIN, left: 8 };
  const series = input.map((s, i) => ({ ...s, label: s.label ?? s.key, color: seriesColor(i, s.color) }));

  const value = (row: ChartDatum, key: string) => Number(row[key]) || 0;
  const totals = data.map((row) =>
    stacked ? series.reduce((sum, s) => sum + value(row, s.key), 0) : Math.max(...series.map((s) => value(row, s.key))),
  );
  const lows = data.map((row) => Math.min(...series.map((s) => value(row, s.key))));
  const low = (bars && !floating) || stacked || zero ? Math.min(0, ...lows) : Math.min(...lows);
  const ticks = niceTicks(low, Math.max(...totals), bare ? 1 : 4);
  const domain: [number, number] = bare ? [Math.min(...lows), Math.max(...totals)] : [ticks[0], ticks.at(-1)!];

  const plotWidth = Math.max(width - margin.left - margin.right, 0);
  const plotHeight = height - margin.top - margin.bottom;
  const band = plotWidth / Math.max(data.length, 1);
  const x = (i: number) => margin.left + (bars ? band * (i + 0.5) : data.length > 1 ? (plotWidth * i) / (data.length - 1) : plotWidth / 2);
  const y = scaleLinear(domain, [margin.top + plotHeight, margin.top]);
  // keep about 48px between x labels
  const every = Math.max(Math.ceil(48 / (bars ? band : plotWidth / Math.max(data.length - 1, 1))), 1);

  const pick = (clientX: number) => {
    const box = ref.current?.getBoundingClientRect();
    if (!box) return;
    const offset = clientX - box.left - margin.left;
    const i = bars ? Math.floor(offset / band) : Math.round((offset / plotWidth) * (data.length - 1));
    setActive(Math.min(Math.max(i, 0), data.length - 1));
  };

  const row = active === null ? null : data[active];
  const context: CartesianContext = {
    data,
    series: effect?.fill ? series.map((s, i) => ({ ...s, color: effect.fill!(s.color, i) })) : series,
    width,
    height,
    x,
    band,
    y,
    top: margin.top,
    floor: y(domain[0]),
    active,
    progress,
  };

  return (
    <figure data-slot={slot} className={cn("flex w-full flex-col gap-3", className)} {...props}>
      {header}
      {!bare && legend && series.length > 1 && <ChartLegend items={series} />}
      <div
        ref={ref}
        role="group"
        aria-roledescription="chart"
        aria-label={`${label}. Use the arrow keys to read each point.`}
        className={cn("relative w-full touch-pan-y", chartFocus)}
        style={{ height }}
        onPointerMove={(event) => pick(event.clientX)}
        onPointerDown={(event) => pick(event.clientX)}
        {...handlers}
      >
        {width > 0 && (
          <svg width={width} height={height} aria-hidden className="block overflow-visible">
            {!bare &&
              grid &&
              ticks.map((tick) => (
                <g key={tick}>
                  <line
                    x1={margin.left}
                    x2={width - margin.right}
                    y1={y(tick)}
                    y2={y(tick)}
                    stroke="currentColor"
                    className={tick === 0 ? "text-foreground/15" : "text-foreground/[0.06]"}
                  />
                  <text
                    x={margin.left - 10}
                    y={y(tick)}
                    dy="0.32em"
                    textAnchor="end"
                    className="fill-muted-foreground font-mono text-[10px] tabular-nums"
                  >
                    {format(tick)}
                  </text>
                </g>
              ))}
            {!bare &&
              data.map((d, i) =>
                i % every === 0 ? (
                  <text
                    key={i}
                    x={x(i)}
                    y={height - 8}
                    textAnchor={bars ? "middle" : i === 0 ? "start" : i === data.length - 1 ? "end" : "middle"}
                    className="fill-muted-foreground text-[11px] font-medium"
                  >
                    {String(d[index])}
                  </text>
                ) : null,
              )}
            {active !== null && !bars && (
              <line
                x1={x(active)}
                x2={x(active)}
                y1={margin.top}
                y2={margin.top + plotHeight}
                stroke="currentColor"
                strokeDasharray="2 4"
                className="text-foreground/25"
              />
            )}
            <EffectLayer effect={effect}>{children(context)}</EffectLayer>
            {overlay?.(context)}
          </svg>
        )}
        <ChartTooltip
          x={active === null ? 0 : x(active)}
          y={active === null ? margin.top : y(totals[active])}
          width={width}
          title={row ? String(row[index]) : undefined}
          rows={
            row
              ? [
                  ...series.map((s) => ({ label: s.label, color: s.color, value: format(value(row, s.key)) })),
                  ...(stacked ? [{ label: "Total", value: format(totals[active!]) }] : []),
                ]
              : null
          }
        />
        <p aria-live="polite" className="sr-only">
          {row ? `${row[index]}: ${series.map((s) => `${s.label} ${format(value(row, s.key))}`).join(", ")}` : ""}
        </p>
      </div>
      <ChartTable
        caption={label}
        columns={[index, ...series.map((s) => s.label)]}
        rows={data.map((d) => [String(d[index]), ...series.map((s) => format(value(d, s.key)))])}
      />
    </figure>
  );
}

export type Point = [x: number, y: number];

export const CHART_COLORS = [
  "var(--chart-1, #4785ff)",
  "var(--chart-2, #2ba597)",
  "var(--chart-3, #e59a2f)",
  "var(--chart-4, #de5f86)",
  "var(--chart-5, #8b6cf0)",
];

// hues are assigned by series position and never cycled; a sixth series reuses gray
export const seriesColor = (index: number, color?: string) =>
  color ?? CHART_COLORS[index] ?? "var(--muted-foreground)";

export function niceTicks(min: number, max: number, count = 4): number[] {
  if (!Number.isFinite(min) || !Number.isFinite(max)) return [0];
  if (min === max) {
    if (min === 0) return [0, 1];
    min = Math.min(0, min);
    max = Math.max(0, max);
  }
  const rough = (max - min) / Math.max(count, 1);
  const power = 10 ** Math.floor(Math.log10(rough));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * power).find((s) => s >= rough)!;
  const start = Math.floor(min / step) * step;
  const end = Math.ceil(max / step) * step;
  const ticks: number[] = [];
  for (let v = start; v <= end + step / 2; v += step) ticks.push(+v.toPrecision(12));
  return ticks;
}

export function scaleLinear([d0, d1]: [number, number], [r0, r1]: [number, number]) {
  const span = d1 - d0 || 1;
  return (value: number) => r0 + ((value - d0) / span) * (r1 - r0);
}

const compact = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });

export const formatCompact = (value: number) => compact.format(value);

const round = (n: number) => +n.toFixed(2);

export function linePath(points: Point[]): string {
  return points.map(([x, y], i) => `${i ? "L" : "M"}${round(x)},${round(y)}`).join("");
}

// a closed polygon whose corners are eased into curves, the corner cut never past half an edge
export function roundedPolygon(points: Point[], radius: number): string {
  const n = points.length;
  if (n < 3) return linePath(points);
  const toward = ([x0, y0]: Point, [x1, y1]: Point, distance: number): Point => {
    const length = Math.hypot(x1 - x0, y1 - y0) || 1;
    const t = Math.min(distance / length, 0.5);
    return [x0 + (x1 - x0) * t, y0 + (y1 - y0) * t];
  };
  const corners = points.map((p, i) => {
    const before = toward(p, points[(i - 1 + n) % n], radius);
    const after = toward(p, points[(i + 1) % n], radius);
    return { before, p, after };
  });
  const [sx, sy] = corners[0].after;
  let d = `M${round(sx)},${round(sy)}`;
  for (let i = 1; i <= n; i++) {
    const { before, p, after } = corners[i % n];
    d += `L${round(before[0])},${round(before[1])}Q${round(p[0])},${round(p[1])} ${round(after[0])},${round(after[1])}`;
  }
  return `${d}Z`;
}

// a closed catmull-rom curve through every point
export function closedCurve(points: Point[]): string {
  const n = points.length;
  if (n < 3) return linePath(points);
  let d = `M${round(points[0][0])},${round(points[0][1])}`;
  for (let i = 0; i < n; i++) {
    const [p0, p1, p2, p3] = [points[(i - 1 + n) % n], points[i], points[(i + 1) % n], points[(i + 2) % n]];
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += `C${round(c1[0])},${round(c1[1])} ${round(c2[0])},${round(c2[1])} ${round(p2[0])},${round(p2[1])}`;
  }
  return `${d}Z`;
}

// monotone cubic (fritsch-carlson) so the curve never overshoots a data point
export function smoothPath(points: Point[]): string {
  const n = points.length;
  if (n < 3) return linePath(points);
  const dx = points.slice(1).map(([x], i) => x - points[i][0]);
  const slope = points.slice(1).map(([, y], i) => (y - points[i][1]) / (dx[i] || 1));
  const tangent = points.map((_, i) => {
    if (i === 0) return slope[0];
    if (i === n - 1) return slope[n - 2];
    const a = slope[i - 1];
    const b = slope[i];
    return a * b <= 0 ? 0 : (3 * (dx[i - 1] + dx[i])) / ((2 * dx[i] + dx[i - 1]) / a + (dx[i] + 2 * dx[i - 1]) / b);
  });
  let d = `M${round(points[0][0])},${round(points[0][1])}`;
  for (let i = 0; i < n - 1; i++) {
    const [x0, y0] = points[i];
    const [x1, y1] = points[i + 1];
    const h = dx[i] / 3;
    d += `C${round(x0 + h)},${round(y0 + h * tangent[i])} ${round(x1 - h)},${round(y1 - h * tangent[i + 1])} ${round(x1)},${round(y1)}`;
  }
  return d;
}

// splits whole cells by share so the counts always add up to the total (largest remainder)
export function allocate(values: number[], cells: number): number[] {
  const sum = values.reduce((a, v) => a + Math.max(v, 0), 0);
  if (sum === 0) return values.map(() => 0);
  const exact = values.map((v) => (Math.max(v, 0) / sum) * cells);
  const counts = exact.map(Math.floor);
  const order = exact.map((e, i) => [e - counts[i], i]).sort((a, b) => b[0] - a[0]);
  const left = cells - counts.reduce((a, c) => a + c, 0);
  for (let k = 0; k < left; k++) counts[order[k][1]]++;
  return counts;
}

export type CalendarCell = { date: string; value: number; week: number; day: number };

const DAY = 86_400_000;
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

// lays iso dates out in week columns starting on monday, with a month label where each month begins
export function calendarCells(data: { date: string; value: number }[]) {
  const days = data
    .map((d) => ({ ...d, time: Date.parse(`${d.date.slice(0, 10)}T00:00:00Z`) }))
    .filter((d) => Number.isFinite(d.time))
    .sort((a, b) => a.time - b.time);
  if (days.length === 0) return { weeks: 0, cells: [] as CalendarCell[], months: [] as { week: number; label: string }[] };
  const first = days[0].time;
  const monday = first - ((new Date(first).getUTCDay() + 6) % 7) * DAY;
  const cells = days.map((d) => {
    const offset = Math.round((d.time - monday) / DAY);
    return { date: d.date.slice(0, 10), value: d.value, week: Math.floor(offset / 7), day: offset % 7 };
  });
  const months: { week: number; label: string }[] = [];
  for (const cell of cells) {
    const month = MONTHS[Number(cell.date.slice(5, 7)) - 1];
    if (months.at(-1)?.label === month || (cell.date.slice(8) !== "01" && months.length > 0)) continue;
    // a partial first month too close to the next label gives way to it
    if (months.length === 1 && months[0].week > cell.week - 3) months.pop();
    months.push({ week: cell.week, label: month });
  }
  return { weeks: cells.at(-1)!.week + 1, cells, months };
}

// a band flowing from (x0, y0) to (x1, y1), y at its top edge, w wide at the start and w1 at the end
export function ribbonPath(x0: number, y0: number, x1: number, y1: number, w: number, w1 = w): string {
  const xm = round((x0 + x1) / 2);
  const [a, b, c, d] = [x0, y0, x1, y1].map(round);
  return `M${a},${b}C${xm},${b} ${xm},${d} ${c},${d}L${c},${round(y1 + w1)}C${xm},${round(y1 + w1)} ${xm},${round(y0 + w)} ${a},${round(y0 + w)}Z`;
}

export type SankeyNodeInput = { id: string; label?: string; color?: string };
export type SankeyLinkInput = { source: string; target: string; value: number };

// columns by longest path from a source, nodes stacked and centred per column, links ordered to avoid crossings at each node
export function sankeyLayout(
  nodes: SankeyNodeInput[],
  links: SankeyLinkInput[],
  { width, height, nodeWidth = 10, gap = 14 }: { width: number; height: number; nodeWidth?: number; gap?: number },
) {
  const index = new Map(nodes.map((n, i) => [n.id, i]));
  const valid = links.filter((l) => index.has(l.source) && index.has(l.target) && l.value > 0 && l.source !== l.target);
  const depth = nodes.map(() => 0);
  // relaxing n times settles any acyclic graph and stops a cycle from looping forever
  for (let pass = 0; pass < nodes.length; pass++)
    for (const l of valid) depth[index.get(l.target)!] = Math.max(depth[index.get(l.target)!], depth[index.get(l.source)!] + 1);
  const columns = Math.max(...depth, 0) + 1;
  const sum = (list: SankeyLinkInput[]) => list.reduce((a, l) => a + l.value, 0);
  const values = nodes.map((n) => Math.max(sum(valid.filter((l) => l.source === n.id)), sum(valid.filter((l) => l.target === n.id))));
  const layers = Array.from({ length: columns }, (_, c) => nodes.map((_, i) => i).filter((i) => depth[i] === c && values[i] > 0));
  const k = Math.min(
    ...layers.filter((l) => l.length).map((l) => (height - gap * (l.length - 1)) / (l.reduce((a, i) => a + values[i], 0) || 1)),
  );
  const placed = nodes.map((n, i) => ({ ...n, index: i, value: values[i], column: depth[i], x: 0, y: 0, h: values[i] * k }));
  for (const layer of layers) {
    const used = layer.reduce((a, i) => a + placed[i].h, 0) + gap * (layer.length - 1);
    let y = (height - used) / 2;
    for (const i of layer) {
      placed[i].x = columns > 1 ? (depth[i] * (width - nodeWidth)) / (columns - 1) : 0;
      placed[i].y = y;
      y += placed[i].h + gap;
    }
  }
  const out = nodes.map(() => 0);
  const into = nodes.map(() => 0);
  const placedLinks = valid.map((l) => ({ ...l, s: index.get(l.source)!, t: index.get(l.target)!, w: l.value * k, sy: 0, ty: 0 }));
  for (const link of [...placedLinks].sort((a, b) => placed[a.t].y - placed[b.t].y)) {
    link.sy = placed[link.s].y + out[link.s];
    out[link.s] += link.w;
  }
  for (const link of [...placedLinks].sort((a, b) => placed[a.s].y - placed[b.s].y)) {
    link.ty = placed[link.t].y + into[link.t];
    into[link.t] += link.w;
  }
  return {
    nodes: placed.filter((n) => n.value > 0),
    links: placedLinks.map((l) => ({ ...l, x0: placed[l.s].x + nodeWidth, x1: placed[l.t].x })),
  };
}

// a bar from the baseline to its value end, rounding only the value end
export function barPath(x: number, base: number, width: number, end: number, radius: number): string {
  const height = Math.abs(base - end);
  if (height === 0 || width <= 0) return "";
  const r = Math.min(radius, width / 2, height);
  const dir = end < base ? 1 : -1;
  const xr = x + width;
  return [
    `M${round(x)},${round(base)}`,
    `L${round(x)},${round(end + dir * r)}`,
    `Q${round(x)},${round(end)} ${round(x + r)},${round(end)}`,
    `L${round(xr - r)},${round(end)}`,
    `Q${round(xr)},${round(end)} ${round(xr)},${round(end + dir * r)}`,
    `L${round(xr)},${round(base)}Z`,
  ].join("");
}

const polar =(cx: number, cy: number, r: number, angle: number): Point => [
  cx + r * Math.sin(angle),
  cy - r * Math.cos(angle),
];

// an open arc along one radius, for stroking with round caps
export function arcLine(cx: number, cy: number, r: number, start: number, end: number): string {
  const sweep = Math.min(end - start, Math.PI * 2 - 1e-4);
  if (sweep <= 0) return "";
  const [x0, y0] = polar(cx, cy, r, start);
  const [x1, y1] = polar(cx, cy, r, start + sweep);
  return `M${round(x0)},${round(y0)}A${r},${r} 0 ${sweep > Math.PI ? 1 : 0} 1 ${round(x1)},${round(y1)}`;
}

// angles in radians, clockwise from twelve o'clock
export function arcPath(cx: number, cy: number, outer: number, inner: number, start: number, end: number): string {
  const sweep = Math.min(end - start, Math.PI * 2 - 1e-4);
  const stop = start + sweep;
  const large = sweep > Math.PI ? 1 : 0;
  const [ox0, oy0] = polar(cx, cy, outer, start);
  const [ox1, oy1] = polar(cx, cy, outer, stop);
  const [ix1, iy1] = polar(cx, cy, inner, stop);
  const [ix0, iy0] = polar(cx, cy, inner, start);
  return [
    `M${round(ox0)},${round(oy0)}`,
    `A${outer},${outer} 0 ${large} 1 ${round(ox1)},${round(oy1)}`,
    inner > 0 ? `L${round(ix1)},${round(iy1)}A${inner},${inner} 0 ${large} 0 ${round(ix0)},${round(iy0)}` : `L${cx},${cy}`,
    "Z",
  ].join("");
}

// bar edges with the days near focus widened up to zoom times, each side scaled back so the point under focus stays put
export function lensEdges(count: number, width: number, focus: number, open: number, zoom: number, reach = 8) {
  const slot = width / count;
  const edges = [0];
  const near: number[] = [];
  for (let i = 0; i < count; i++) {
    const d = Math.abs((i + 0.5) * slot - focus) / (reach * slot);
    const g = d < 1 ? (1 - d * d) ** 2 : 0;
    near.push(g);
    edges.push(edges[i] + slot * (1 + (zoom - 1) * open * g));
  }
  const total = edges[count];
  const at = Math.min(Math.max(focus / slot, 0), count - 1e-6);
  const i = Math.floor(at);
  const pivot = edges[i] + (at - i) * (edges[i + 1] - edges[i]);
  const to = Math.min(Math.max(focus, 0), width);
  const left = pivot > 0 ? to / pivot : 1;
  const right = total > pivot ? (width - to) / (total - pivot) : 1;
  return { edges: edges.map((x) => (x <= pivot ? x * left : to + (x - pivot) * right)), near };
}
